import {search,preferences,neighbours,audioCredit,routeKind,adjacentImages,retryUrl} from './domain.mjs';
const copy={zh:{heading:'遗世独立',count:'幅作品',disclaimer:'本导览内容由 AI 辅助生成，请以纸质画册为准。',search:'搜索编号或作品名称',empty:'未找到作品',back:'返回作品目录',listen:'听介绍',prev:'上一个',next:'下一个',unavailable:'音频暂时无法播放',image:'图片暂时无法显示',missing:'英文介绍尚未提供。以下保留意大利文标题。',play:'播放',pause:'暂停',loading:'正在加载…',notfound:'未找到这幅作品',failed:'作品目录暂时无法加载，请重试。',retry:'重试'},it:{heading:'Altrove',count:'opere',disclaimer:'I testi di questa guida sono stati generati con l’ausilio dell’intelligenza artificiale. Fa fede il catalogo cartaceo.',search:'Cerca numero o titolo',empty:'Nessuna opera trovata',back:'Torna all’elenco',listen:'Ascolta',prev:'Precedente',next:'Successivo',unavailable:'Audio temporaneamente non disponibile',image:'Immagine non disponibile',missing:'Il testo inglese non è ancora disponibile.',play:'Riproduci',pause:'Pausa',loading:'Caricamento…',notfound:'Opera non trovata',failed:'Impossibile caricare le opere. Riprova.',retry:'Riprova'},en:{heading:'Altrove',count:'artworks',disclaimer:'The texts in this guide were generated with the assistance of AI. Please refer to the printed catalogue as the authoritative version.',search:'Search artwork number or title',empty:'No artworks found',back:'Back to artworks',listen:'Listen',prev:'Previous',next:'Next',unavailable:'Audio temporarily unavailable',image:'Image unavailable',missing:'English text has not been provided. Italian titles are shown.',play:'Play',pause:'Pause',loading:'Loading…',notfound:'Artwork not found',failed:'Unable to load artworks. Please retry.',retry:'Retry'}};
let stored=null;try{stored=localStorage.getItem('altrove.preferences.v1')}catch{}
let pref=preferences(stored),works=[],query='',active=null,generation=0;
const main=document.querySelector('main'),audio=new Audio(),player=document.querySelector('#player');audio.preload='none';
const text=()=>copy[pref.language];
function el(tag,content,cls){const node=document.createElement(tag);if(content!==undefined)node.textContent=content;if(cls)node.className=cls;return node}
function save(){try{localStorage.setItem('altrove.preferences.v1',JSON.stringify(pref))}catch{}}
function settings(){document.documentElement.lang=pref.language;document.documentElement.dataset.size=pref.size;document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===pref.language)));document.querySelectorAll('button[data-size]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.size===pref.size)));}
function stop(){generation++;audio.pause();audio.removeAttribute('src');audio.load();player.hidden=true;document.body.classList.remove('playing');document.querySelector('#audio-status').textContent='';}
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{stop();pref.language=b.dataset.lang;save();settings();render(false)});
document.querySelectorAll('button[data-size]').forEach(b=>b.onclick=()=>{pref.size=b.dataset.size;save();settings()});
function link(label,url,cls){const a=el('a',label,cls);a.href=url;return a}
function catalogue(){active=null;const heading=el('div',undefined,'catalogue-head');heading.append(el('h1',text().heading),el('span',({zh:'开篇 + 33 幅作品',it:'Introduzione + 33 opere',en:'Introduction + 33 artworks'}[pref.language]),'count'));main.append(heading,el('p',text().disclaimer,'disclaimer'));const wrap=el('div',undefined,'search-wrap'),input=el('input');input.type='search';input.placeholder=text().search;input.setAttribute('aria-label',text().search);input.value=query;const clear=el('button','×','clear');clear.setAttribute('aria-label',pref.language==='zh'?'清除搜索':'Clear');wrap.append(input,clear);main.append(wrap);const rows=el('div',undefined,'rows');main.append(rows);const fill=()=>{rows.replaceChildren();const found=search(works,query);if(!found.length){rows.append(el('p',text().empty,'empty'));return}for(const w of found){const a=link('',`#/works/${w.id}`,'row');a.append(el('span',w.displayId||w.id,'number'),el('span',w.title[pref.language],'row-title'));rows.append(a)}};input.oninput=()=>{query=input.value;fill()};clear.onclick=()=>{query='';input.value='';fill();input.focus()};fill();}
function detail(w){active=w;const article=el('article',undefined,'detail');article.append(link('← '+text().back,'#/','back'));const fig=el('div',undefined,w.images?'art-pair':'');let prefetched=false;for(const item of w.images||[{src:w.image,title:w.title}]){const frame=el('figure',undefined,'art-image'),img=el('img');let retried=false;img.src=item.src;img.alt=item.title[pref.language];img.decoding='async';img.onload=()=>{frame.classList.add('loaded');if(!prefetched){prefetched=true;for(const src of adjacentImages(works,w.id)){const preload=new Image();preload.src=src}}};img.onerror=()=>{if(!retried){retried=true;img.src=retryUrl(item.src);return}frame.classList.add('loaded');frame.replaceChildren(el('p',text().image,'audio-note'))};frame.append(img);if(w.images)frame.append(el('figcaption',item.title[pref.language]));fig.append(frame)}article.append(fig,el('p','NO. '+(w.displayId||w.id),'eyebrow'),el('h1',w.title[pref.language]),el('p',w.meta[pref.language],'meta'));const listen=el('button',text().listen,'listen');const source=w.audio[pref.language];const note=el('p',source?audioCredit(pref.language):'','audio-note');note.setAttribute('role','status');if(source){audio.preload='metadata';audio.src=source}listen.onclick=()=>{if(!source){note.textContent=text().unavailable;return}begin(source)};article.append(listen,note);const essay=el('section',undefined,'essay');w.body[pref.language].forEach((p,i)=>essay.append(el(w.id!=='00'&&i===0&&p.length<80?'h2':'p',p)));article.append(essay);const nav=el('nav',undefined,'neighbours');nav.setAttribute('aria-label',text().prev+' / '+text().next);const n=neighbours(works,w.id);for(const [direction,target] of [['prev',n.previous],['next',n.next]]){if(!target)continue;const a=link('',`#/works/${target.id}`,!n.previous?'next-only':'');a.append(el('span',text()[direction]),el('strong',(target.displayId||target.id)+' · '+target.title[pref.language]));nav.append(a)}article.append(nav,link(text().back,'#/','bottom-back'));main.append(article);document.title=w.title[pref.language]+' · ALTROVE';}
function render(focus=true){main.replaceChildren();document.title=text().heading+' · ALTROVE';const hash=location.hash,kind=routeKind(hash);const match=/^#\/works\/(\d{2})$/.exec(hash);if(kind==='catalogue')catalogue();else{const w=kind==='detail'&&match&&works.find(w=>w.id===match[1]||w.aliases?.includes(match[1]));if(w)detail(w);else main.append(el('h1',text().notfound),link(text().back,'#/','back'))}if(focus){window.scrollTo(0,0);const h=main.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}}}
async function begin(src){stop();const token=generation;player.hidden=false;document.body.classList.add('playing');document.querySelector('#audio-language').textContent=pref.language.toUpperCase();document.querySelector('#audio-status').textContent=text().loading;update();for(const candidate of [src,retryUrl(src)]){audio.src=candidate;try{await audio.play();if(token!==generation)return;update();return}catch{if(token!==generation)return}}document.querySelector('#audio-status').textContent=text().unavailable}
const fmt=s=>Number.isFinite(s)?Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0'):'--:--';
function update(){document.querySelector('#toggle').textContent=audio.paused?text().play:text().pause;document.querySelector('#time').textContent=fmt(audio.currentTime)+' / '+fmt(audio.duration);const seek=document.querySelector('#seek');seek.disabled=!Number.isFinite(audio.duration)||audio.duration<=0;seek.value=seek.disabled?0:audio.currentTime/audio.duration*100;}
document.querySelector('#toggle').onclick=async()=>{if(!audio.paused)audio.pause();else{try{await audio.play()}catch{document.querySelector('#audio-status').textContent=text().unavailable}}};document.querySelector('#seek').oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)/100*audio.duration};
for(const event of ['timeupdate','durationchange','pause','ended','loadedmetadata'])audio.addEventListener(event,update);audio.addEventListener('playing',()=>{document.querySelector('#audio-status').textContent='';update()});audio.addEventListener('waiting',()=>{document.querySelector('#audio-status').textContent=text().loading});audio.addEventListener('error',()=>{document.querySelector('#audio-status').textContent=text().unavailable});
window.addEventListener('hashchange',()=>{stop();render()});
settings();
async function load(){try{const response=await fetch('data.json');if(!response.ok)throw Error();works=await response.json();if(!location.hash)history.replaceState(null,'',location.pathname+location.search+'#/');render(false);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch{main.replaceChildren(el('p',text().failed));const retry=el('button',text().retry);retry.onclick=load;main.append(retry)}}load();
